class ValidationError extends Error {}

// createUser({ name, age }) returns { name, age } or throws a ValidationError.
// Rules:
//   name: a string that isn't empty after trimming.
//   age: a whole number from 0 to 150. It comes from a form, so it may be a number
//        or a numeric string like "42". The returned age is always a number.
function createUser(input) {
  return { name: input.name, age: input.age };
}

module.exports = { createUser, ValidationError };

input.new_string:
const { createUser, ValidationError } = require('../users');

test('coerces numeric string age', () => {
  assert.deepStrictEqual(createUser({ name: 'Bo', age: '42' }), { name: 'Bo', age: 42 });
  assert.strictEqual(createUser({ name: 'Bo', age: 0 }).age, 0);
  assert.strictEqual(createUser({ name: 'Bo', age: '150' }).age, 150);
});

test('rejects invalid input', () => {
  const bad = [
    undefined, null, 'x', {},
    { name: '', age: 1 }, { name: '   ', age: 1 }, { name: 5, age: 1 }, { age: 1 },
    { name: 'A' }, { name: 'A', age: -1 }, { name: 'A', age: 151 },
    { name: 'A', age: 4.5 }, { name: 'A', age: '4.5' }, { name: 'A', age: '' },
    { name: 'A', age: 'abc' }, { name: 'A', age: NaN }, { name: 'A', age: Infinity },
    { name: 'A', age: null }, { name: 'A', age: '-3' }, { name: 'A', age: '1e2' },
  ];
  for (const b of bad) assert.throws(() => createUser(b), ValidationError, JSON.stringify(b));
});

